export const CLIENT_ORG_COMPANY_OPTIONS: { label: string; value: string }[] =
  CLIENT_ORG_STATIC_COMPANIES.map(c => ({ label: c.companyName, value: c.id }));

export function findStaticCompanyById(id: string | null | undefined): StaticCompany | undefined {
  if (!id) return undefined;
  return CLIENT_ORG_STATIC_COMPANIES.find(c => c.id === id);
}

export function findStaticDivisionByCode(divisionCode: string | null | undefined): StaticDivision | undefined {
  if (!divisionCode) return undefined;
  for (const company of CLIENT_ORG_STATIC_COMPANIES) {
    const division = company.divisions.find(b => b.divisionCode === divisionCode);
    if (division) return division;
  }
  return undefined;
}

export function findStaticSubDivision(
  divisionCode: string | null | undefined,
  subDivisionName: string | null | undefined,
): StaticSubDivision | undefined {
  const division = findStaticDivisionByCode(divisionCode);
  return division?.subDivisions.find(d => d.subDivisionName === subDivisionName);
}

export function findStaticSubDivisionByCode(subDivisionCode: string | null | undefined): StaticSubDivision | undefined {
  if (!subDivisionCode) return undefined;
  for (const company of CLIENT_ORG_STATIC_COMPANIES) {
    for (const division of company.divisions) {
      const dept = division.subDivisions.find(d => d.subDivisionCode === subDivisionCode);
      if (dept) return dept;
    }
  }
  return undefined;
}

/** Flat search across every company/division/sub-division for a scope or sub-scope by id. */
export function findStaticScopeById(id: string | null | undefined): StaticScope | undefined {
  if (!id) return undefined;
  for (const company of CLIENT_ORG_STATIC_COMPANIES) {
    for (const division of company.divisions) {
      for (const dept of division.subDivisions) {
        const scope = dept.scopes.find(s => s.id === id);
        if (scope) return scope;
      }
    }
  }
  return undefined;
}

/** All sub-scopes (flat sibling records with parentScopeId === parentId) of a top-level scope. */
export function subScopesOf(parentId: string): StaticScope[] {
  const result: StaticScope[] = [];
  for (const company of CLIENT_ORG_STATIC_COMPANIES) {
    for (const division of company.divisions) {
      for (const dept of division.subDivisions) {
        for (const scope of dept.scopes) {
          if (scope.parentScopeId === parentId) result.push(scope);
        }
      }
    }
  }
  return result;
}

/* ── Mutations ────────────────────────────────────────────────────────────
 * There's no backend behind this page — the profile/Add-Edit drawers write
 * straight into this in-memory array so client-organizational-chart.html
 * reflects edits immediately. Editing merges in place (keeps position);
 * a changed company/division/sub-division key moves the record to its new
 * parent's array instead of leaving a stale copy behind.
 */

export function editStaticCompany(id: string, updates: CompanyEditableFields): void {
  const company = CLIENT_ORG_STATIC_COMPANIES.find(c => c.id === id);
  if (!company) return;
  Object.assign(company, updates);
}

export function setCompanyStatus(id: string, status: CompanyRecordStatus): void {
  const company = findStaticCompanyById(id);
  if (company) company.status = status;
}

export function editStaticDivision(divisionCode: string, updates: DivisionEditableFields): void {
  for (const company of CLIENT_ORG_STATIC_COMPANIES) {
    const idx = company.divisions.findIndex(b => b.divisionCode === divisionCode);
    if (idx === -1) continue;
    company.divisions[idx] = { ...company.divisions[idx], ...updates, divisionCode };
    return;
  }
}

export function setDivisionStatus(divisionCode: string, status: DivisionStatus): void {
  const division = findStaticDivisionByCode(divisionCode);
  if (division) division.status = status;
}

export function editStaticSubDivision(subDivisionCode: string, updates: SubDivisionEditableFields): void {
  for (const company of CLIENT_ORG_STATIC_COMPANIES) {
    for (const division of company.divisions) {
      const idx = division.subDivisions.findIndex(d => d.subDivisionCode === subDivisionCode);
      if (idx === -1) continue;
      division.subDivisions[idx] = { ...division.subDivisions[idx], ...updates, subDivisionCode };
      return;
    }
  }
}

export function setSubDivisionStatus(subDivisionCode: string, status: SubDivisionStatus): void {
  const dept = findStaticSubDivisionByCode(subDivisionCode);
  if (dept) dept.status = status;
}

function nextScopeId(): string {
  let max = 0;
  for (const company of CLIENT_ORG_STATIC_COMPANIES) {
    for (const division of company.divisions) {
      for (const dept of division.subDivisions) {
        for (const scope of dept.scopes) {
          const n = parseInt(scope.id.replace('SC-', ''), 10);
          if (!isNaN(n) && n > max) max = n;
        }
      }
    }
  }
  return `SC-${String(max + 1).padStart(4, '0')}`;
}

/** Adds a brand-new scope or sub-scope — whether it's a scope or sub-scope is
 * entirely determined by `fields.parentScopeId` (null vs. an existing top-level
 * scope's id). Not wired to any button on this page today, but kept for parity
 * with audit-scope-static-data.ts's mutation surface. */
export function upsertStaticScope(
  companyId: string,
  divisionCode: string,
  subDivisionName: string,
  fields: Omit<StaticScope, 'id'>,
): StaticScope | undefined {
  const dept = CLIENT_ORG_STATIC_COMPANIES
    .find(c => c.id === companyId)?.divisions
    .find(b => b.divisionCode === divisionCode)?.subDivisions
    .find(d => d.subDivisionName === subDivisionName);
  if (!dept) return undefined;
  const scope: StaticScope = { ...fields, id: nextScopeId(), createdAt: new Date().toISOString() };
  dept.scopes.push(scope);
  return scope;
}

/** Updates the scope/sub-scope previously identified by `id`, merging `updates`
 * onto the existing record in place (or moving it if the sub-division changed). */
export function editStaticScope(id: string, updates: Omit<StaticScope, 'id'>): void {
  for (const company of CLIENT_ORG_STATIC_COMPANIES) {
    for (const division of company.divisions) {
      for (const dept of division.subDivisions) {
        const idx = dept.scopes.findIndex(s => s.id === id);
        if (idx === -1) continue;

        const merged: StaticScope = { ...dept.scopes[idx], ...updates, id };
        const targetDept = CLIENT_ORG_STATIC_COMPANIES
          .find(c => c.id === updates.company)?.divisions
          .find(b => b.divisionCode === updates.divisionCode)?.subDivisions
          .find(d => d.subDivisionName === updates.subDivisionName);
        if (!targetDept) return;

        if (targetDept === dept) {
          dept.scopes[idx] = merged;
        } else {
          dept.scopes.splice(idx, 1);
          targetDept.scopes.push(merged);
        }
        return;
      }
    }
  }
}

/** Sets a scope/sub-scope's `status` in place (used by the Activate/Deactivate action). */
export function setScopeStatus(id: string, status: ScopeRecordStatus): void {
  const scope = findStaticScopeById(id);
  if (scope) scope.status = status;
}
